import React, { useState, useEffect, useCallback, useRef } from "react";
import { RefreshCw, Bell, Activity, TrendingUp, GitBranch, Waves } from "lucide-react";

/* ---------------- indicator math ---------------- */
const sma = (v, p) => (v.length < p ? null : v.slice(-p).reduce((a, b) => a + b, 0) / p);
function rsi(c, period = 14) {
  if (c.length < period + 1) return null;
  let g = 0, l = 0;
  for (let i = 1; i <= period; i++) { const d = c[i] - c[i - 1]; if (d >= 0) g += d; else l -= d; }
  let ag = g / period, al = l / period;
  for (let i = period + 1; i < c.length; i++) {
    const d = c[i] - c[i - 1];
    ag = (ag * (period - 1) + (d > 0 ? d : 0)) / period;
    al = (al * (period - 1) + (d < 0 ? -d : 0)) / period;
  }
  if (al === 0) return 100;
  return 100 - 100 / (1 + ag / al);
}
function emaSeries(vals, p) {
  const k = 2 / (p + 1), out = [];
  let prev;
  vals.forEach((v, i) => {
    if (i < p - 1) { out.push(null); return; }
    if (i === p - 1) { prev = vals.slice(0, p).reduce((a, b) => a + b, 0) / p; out.push(prev); return; }
    prev = v * k + prev * (1 - k); out.push(prev);
  });
  return out;
}
function macd(c) {
  const e12 = emaSeries(c, 12), e26 = emaSeries(c, 26);
  const line = c.map((_, i) => (e12[i] != null && e26[i] != null ? e12[i] - e26[i] : null));
  const vals = line.filter((v) => v != null);
  const sig = emaSeries(vals, 9);
  const lm = vals[vals.length - 1], ls = sig[sig.length - 1];
  if (lm == null || ls == null) return null;
  return { hist: lm - ls };
}
const clamp = (x, lo, hi) => Math.max(lo, Math.min(hi, x));

function buildScore(c) {
  const price = c[c.length - 1];
  const r = rsi(c), s20 = sma(c, 20), s50 = sma(c, 50), s200 = sma(c, 200), m = macd(c);
  const parts = [];
  if (r != null) parts.push({ key: "RSI", label: "RSI (14)", sub: clamp(r, 0, 100), w: 0.2, raw: r.toFixed(1) });
  if (s50) parts.push({ key: "ma50", label: "Prijs vs MA50", sub: clamp(50 + (price / s50 - 1) * 1000, 0, 100), w: 0.25, raw: ((price / s50 - 1) * 100).toFixed(2) + "%" });
  if (s20 && s50) parts.push({ key: "cross", label: "MA20 vs MA50", sub: clamp(50 + (s20 / s50 - 1) * 2500, 0, 100), w: 0.2, raw: ((s20 / s50 - 1) * 100).toFixed(2) + "%" });
  if (s200) parts.push({ key: "ma200", label: "Prijs vs MA200", sub: clamp(50 + (price / s200 - 1) * 500, 0, 100), w: 0.2, raw: ((price / s200 - 1) * 100).toFixed(2) + "%" });
  if (m) parts.push({ key: "macd", label: "MACD histogram", sub: clamp(50 + (m.hist / price) * 20000, 0, 100), w: 0.15, raw: m.hist.toFixed(1) });
  const wsum = parts.reduce((a, p) => a + p.w, 0);
  const score = parts.reduce((a, p) => a + p.sub * p.w, 0) / (wsum || 1);
  return { score, parts };
}
const verdict = (s) => (s < 25 ? "Sterk bearish" : s < 45 ? "Bearish" : s < 55 ? "Neutraal" : s < 75 ? "Bullish" : "Sterk bullish");
const hueOf = (s) => (s / 100) * 140;

/* ---------------- data sources ---------------- */
async function fetchBinance(bsym, frame) {
  const [tRes, kRes] = await Promise.all([
    fetch(`https://api.binance.com/api/v3/ticker/24hr?symbol=${bsym}`),
    fetch(`https://api.binance.com/api/v3/klines?symbol=${bsym}&interval=${frame}&limit=250`),
  ]);
  if (!tRes.ok || !kRes.ok) throw new Error("binance");
  const t = await tRes.json(); const k = await kRes.json();
  return { closes: k.map((x) => parseFloat(x[4])), price: parseFloat(t.lastPrice), change: parseFloat(t.priceChangePercent), changeLabel: "24u" };
}
const YF = {
  "4h": { interval: "60m", range: "3mo" },
  "1d": { interval: "1d", range: "2y" },
  "1w": { interval: "1wk", range: "5y" },
  "1M": { interval: "1mo", range: "10y" },
};
const proxy = (u) => `https://api.allorigins.win/raw?url=${encodeURIComponent(u)}`;
async function fetchYahoo(ysym, frame) {
  const { interval, range } = YF[frame];
  const res = await fetch(proxy(`https://query1.finance.yahoo.com/v8/finance/chart/${encodeURIComponent(ysym)}?interval=${interval}&range=${range}`));
  if (!res.ok) throw new Error("yahoo");
  const r = (await res.json()).chart.result[0];
  const closes = r.indicators.quote[0].close.filter((v) => v != null);
  const price = r.meta.regularMarketPrice;
  const prev = r.meta.chartPreviousClose ?? closes[closes.length - 2];
  return { closes, price, change: (price / prev - 1) * 100, changeLabel: "1d" };
}
async function fetchQuote(cfg) {
  if (cfg.src === "yahoo") {
    const res = await fetch(proxy(`https://query1.finance.yahoo.com/v8/finance/chart/${encodeURIComponent(cfg.q)}?interval=1d&range=5d`));
    if (!res.ok) throw new Error("yq");
    const m = (await res.json()).chart.result[0].meta;
    const prev = m.chartPreviousClose ?? m.previousClose;
    return { price: m.regularMarketPrice, chg: prev ? (m.regularMarketPrice / prev - 1) * 100 : null };
  }
  const res = await fetch(`https://api.binance.com/api/v3/ticker/24hr?symbol=${cfg.q}`);
  if (!res.ok) throw new Error("bq");
  const j = await res.json();
  return { price: parseFloat(j.lastPrice), chg: parseFloat(j.priceChangePercent) };
}

const ASSETS = [
  { sym: "BTC", label: "BTC", src: "binance", q: "BTCUSDT" },
  { sym: "GOLD", label: "Goud", src: "binance", q: "PAXGUSDT" },
  { sym: "SPX", label: "S&P 500", src: "yahoo", q: "^GSPC" },
];
const FRAMES = [
  { k: "4h", label: "4u" },
  { k: "1d", label: "Dag" },
  { k: "1w", label: "Week" },
  { k: "1M", label: "Maand" },
];
const ICONS = { RSI: Activity, ma50: TrendingUp, cross: GitBranch, ma200: TrendingUp, macd: Waves };

/* ---------------- beast photos ---------------- */
const BULL_IMG = "data:image/webp;base64,";
const BEAR_IMG = "data:image/webp;base64,";

/* ---------------- app ---------------- */
export default function App() {
  const [asset, setAsset] = useState("BTC");
  const [frame, setFrame] = useState("1d");
  const [st, setSt] = useState({ status: "loading", price: null, change: null, changeLabel: "24u", score: 50, parts: [], updated: null });
  const [prices, setPrices] = useState({});
  const prevP = useRef({});
  const flashId = useRef(0);
  const timer = useRef(null);
  const pTimer = useRef(null);
  const cfg = ASSETS.find((a) => a.sym === asset);

  const loadScore = useCallback(async () => {
    try {
      const d = cfg.src === "yahoo" ? await fetchYahoo(cfg.q, frame) : await fetchBinance(cfg.q, frame);
      const { score, parts } = buildScore(d.closes);
      setSt({ status: "ok", price: d.price, change: d.change, changeLabel: d.changeLabel, score, parts, updated: new Date() });
    } catch (e) {
      setSt((s) => ({ ...s, status: "error" }));
    }
  }, [asset, frame, cfg]);

  const loadPrices = useCallback(async () => {
    const results = await Promise.allSettled(ASSETS.map((a) => fetchQuote(a)));
    setPrices((cur) => {
      const next = { ...cur };
      results.forEach((r, i) => {
        if (r.status !== "fulfilled" || r.value == null) return;
        const sym = ASSETS[i].sym;
        const p = r.value.price, chg = r.value.chg;
        const old = prevP.current[sym];
        let dir = null;
        if (old != null && p > old) dir = "up";
        else if (old != null && p < old) dir = "down";
        prevP.current[sym] = p;
        next[sym] = { p, chg, dir, id: dir ? ++flashId.current : (cur[sym]?.id || 0) };
      });
      return next;
    });
  }, []);

  useEffect(() => {
    setSt((s) => ({ ...s, price: null, change: null, status: "loading" }));
    loadScore();
    timer.current = setInterval(loadScore, 45000);
    return () => clearInterval(timer.current);
  }, [loadScore]);

  useEffect(() => {
    loadPrices();
    pTimer.current = setInterval(loadPrices, 20000);
    return () => clearInterval(pTimer.current);
  }, [loadPrices]);

  const { score, price, change, changeLabel, parts, status, updated } = st;
  const t = clamp(score, 0, 100) / 100;
  const bear = 1 - t, bull = t;
  const hue = hueOf(score);
  const accent = `hsl(${hue} 75% 56%)`;
  const bg = `radial-gradient(130% 90% at 50% -20%, hsl(${hue} 50% 12%) 0%, hsl(${hue} 42% 6%) 45%, #08070a 100%)`;

  const beastStyle = (strength, side) => ({
    position: "fixed", bottom: "2%", ...(side === "left" ? { right: "calc(50% + 6px)" } : { left: "calc(50% + 6px)" }), height: "min(30vh,215px)", zIndex: 1, pointerEvents: "none",
    opacity: 0.5 + strength * 0.5,
    filter: `brightness(${0.7 + strength * 0.6}) saturate(${0.85 + strength * 0.55}) drop-shadow(0 0 ${16 + strength * 55}px ${side === "left" ? "rgba(225,45,45," : "rgba(45,205,95,"}${0.25 + strength * 0.55}))`,
    transition: "opacity 1.1s ease, filter 1.1s ease",
  });
  const money = (n) => (n == null ? "—" : "$" + n.toLocaleString("en-US", { minimumFractionDigits: 2, maximumFractionDigits: 2 }));

  return (
    <div style={{ position: "relative", minHeight: "100vh", background: bg, transition: "background 1200ms ease", fontFamily: "'Space Grotesk',system-ui,sans-serif", color: "#ece9e3", overflow: "hidden" }}>
      <style>{`
        @import url('https://fonts.googleapis.com/css2?family=Space+Grotesk:wght@400;500;600;700&family=JetBrains+Mono:wght@400;500;700&display=swap');
        .mono{font-family:'JetBrains Mono',monospace;font-variant-numeric:tabular-nums;}
        @keyframes pulse{0%,100%{opacity:1}50%{opacity:.3}}
        @keyframes rise{from{opacity:0;transform:translateY(14px)}to{opacity:1;transform:translateY(0)}}
        @keyframes flashUp{0%{background:rgba(45,205,95,.55)}100%{background:rgba(255,255,255,.05)}}
        @keyframes flashDown{0%{background:rgba(225,55,55,.6)}100%{background:rgba(255,255,255,.05)}}
        .rise{animation:rise .6s ease both;}
        button{font-family:inherit;}
        @media (prefers-reduced-motion: reduce){*{animation-duration:.06ms!important;transition-duration:.06ms!important}}
      `}</style>

      {/* color blooms */}
      <div style={{ position: "fixed", inset: 0, zIndex: 0, pointerEvents: "none", background: `radial-gradient(58% 55% at 0% 100%, hsla(2,85%,45%,${0.12 + bear * 0.42}) 0%, transparent 62%)`, transition: "background 1.1s ease" }} />
      <div style={{ position: "fixed", inset: 0, zIndex: 0, pointerEvents: "none", background: `radial-gradient(58% 55% at 100% 100%, hsla(140,75%,42%,${0.12 + bull * 0.42}) 0%, transparent 62%)`, transition: "background 1.1s ease" }} />

      {/* beasts */}
      <div aria-hidden style={beastStyle(bear, "left")}><img src={BEAR_IMG} alt="" draggable={false} style={{ height: "100%", width: "auto", display: "block" }} /></div>
      <div aria-hidden style={beastStyle(bull, "right")}><img src={BULL_IMG} alt="" draggable={false} style={{ height: "100%", width: "auto", display: "block" }} /></div>

      {/* vignette */}
      <div style={{ position: "fixed", inset: 0, zIndex: 2, pointerEvents: "none", background: "radial-gradient(115% 85% at 50% 38%, transparent 42%, rgba(0,0,0,.6) 100%)" }} />

      {/* content */}
      <div style={{ position: "relative", zIndex: 3, maxWidth: 460, margin: "0 auto", padding: "20px 18px 36px", minHeight: "100vh", display: "flex", flexDirection: "column" }}>
        {/* header */}
        <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", marginBottom: 18 }}>
          <div style={{ fontSize: 15, fontWeight: 700, letterSpacing: 1.5 }}>BULLS <span style={{ opacity: 0.5 }}>&amp;</span> BEARS</div>
          <div style={{ display: "flex", gap: 10, alignItems: "center" }}>
            <span style={{ display: "flex", alignItems: "center", gap: 6 }}>
              <span style={{ width: 7, height: 7, borderRadius: 99, background: status === "ok" ? accent : "#777", animation: status === "ok" ? "pulse 1.8s infinite" : "none", boxShadow: `0 0 10px ${accent}` }} />
              <span className="mono" style={{ fontSize: 10, letterSpacing: 1.5, opacity: 0.6 }}>{status === "error" ? "OFFLINE" : status === "loading" ? "LADEN" : "LIVE"}</span>
            </span>
            <button onClick={() => { loadScore(); loadPrices(); }} style={{ background: "rgba(255,255,255,.06)", border: "1px solid rgba(255,255,255,.12)", color: "#ece9e3", borderRadius: 9, padding: "7px", cursor: "pointer", display: "flex" }}><RefreshCw size={15} /></button>
          </div>
        </div>

        {/* assets with live price + day change */}
        <div style={{ display: "flex", gap: 8, marginBottom: 22 }}>
          {ASSETS.map((a) => {
            const active = asset === a.sym;
            const pd = prices[a.sym];
            return (
              <button key={a.sym} onClick={() => setAsset(a.sym)}
                style={{ flex: 1, padding: 0, borderRadius: 12, cursor: "pointer", overflow: "hidden", textAlign: "center",
                  border: `1px solid ${active ? accent : "rgba(255,255,255,.1)"}`,
                  background: active ? `hsl(${hue} 55% 14%)` : "rgba(255,255,255,.03)", transition: "border .4s, background .4s" }}>
                <div className="mono" style={{ padding: "9px 0 6px", fontSize: 13, fontWeight: 600, color: active ? "#fff" : "rgba(236,233,227,.7)" }}>{a.label}</div>
                <div key={pd?.id ?? "x"}
                  style={{ background: "rgba(255,255,255,.05)",
                    animation: pd?.dir === "up" ? "flashUp .9s ease" : pd?.dir === "down" ? "flashDown .9s ease" : "none" }}>
                  <div className="mono" style={{ fontSize: 12, fontWeight: 500, padding: "6px 2px 1px", color: "#fff" }}>{pd?.p != null ? money(pd.p) : "—"}</div>
                  <div className="mono" style={{ fontSize: 10.5, fontWeight: 600, padding: "0 2px 6px", color: pd?.chg == null ? "rgba(236,233,227,.4)" : pd.chg >= 0 ? "hsl(140 60% 62%)" : "hsl(2 72% 66%)" }}>
                    {pd?.chg != null ? (pd.chg >= 0 ? "\u25B2 " : "\u25BC ") + Math.abs(pd.chg).toFixed(2) + "%" : "—"}
                  </div>
                </div>
              </button>
            );
          })}
        </div>

        {/* price (selected) */}
        <div style={{ textAlign: "center" }}>
          <div className="mono" style={{ fontSize: 42, fontWeight: 700, letterSpacing: -1.5, lineHeight: 1, textShadow: "0 2px 22px rgba(0,0,0,.7)" }}>{money(price)}</div>
          <div className="mono" style={{ marginTop: 7, fontSize: 13, color: change >= 0 ? "hsl(140 60% 62%)" : "hsl(2 72% 64%)" }}>
            {change != null ? (change >= 0 ? "\u25B2 " : "\u25BC ") + Math.abs(change).toFixed(2) + "%  " + changeLabel : ""}
          </div>
        </div>

        {/* score */}
        <div style={{ textAlign: "center", margin: "24px 0 4px" }}>
          <div className="mono" style={{ fontSize: 78, fontWeight: 700, lineHeight: 0.9, color: accent, textShadow: `0 0 46px ${accent}66, 0 2px 20px rgba(0,0,0,.6)` }}>{Math.round(score)}</div>
          <div style={{ fontSize: 21, fontWeight: 600, marginTop: 6, letterSpacing: 0.3, textShadow: "0 2px 14px rgba(0,0,0,.6)" }}>{verdict(score)}</div>
        </div>

        {/* tug-of-war bar + heads */}
        <div style={{ margin: "18px 2px 8px" }}>
          <div style={{ position: "relative", height: 16, borderRadius: 99, background: "linear-gradient(90deg, hsl(2 70% 45%) 0%, hsl(42 80% 48%) 50%, hsl(140 60% 42%) 100%)", opacity: 0.9, boxShadow: "inset 0 1px 4px rgba(0,0,0,.5)" }}>
            <div style={{ position: "absolute", top: "50%", left: `${score}%`, width: 22, height: 22, borderRadius: 99, background: "#fff", boxShadow: `0 0 18px ${accent}, 0 0 4px #000`, transform: "translate(-50%,-50%)", transition: "left 1.1s cubic-bezier(.34,1.2,.5,1)", border: `3px solid ${accent}` }} />
          </div>
          <div style={{ display: "flex", justifyContent: "space-between", alignItems: "flex-end", marginTop: 10 }}>
            <div style={{ display: "flex", alignItems: "flex-end", gap: 7 }}>
              <div style={{ width: 52, filter: `drop-shadow(0 0 ${5 + bear * 15}px rgba(225,45,45,${0.2 + bear * 0.5}))`, opacity: 0.6 + bear * 0.4, transition: "all .9s ease" }}><img src={BEAR_IMG} alt="" draggable={false} style={{ width: "100%", height: "auto", display: "block" }} /></div>
              <span style={{ fontSize: 12, opacity: 0.75, fontWeight: 600, paddingBottom: 6 }}>Bears</span>
            </div>
            <div style={{ display: "flex", alignItems: "flex-end", gap: 7 }}>
              <span style={{ fontSize: 12, opacity: 0.75, fontWeight: 600, paddingBottom: 6 }}>Bulls</span>
              <div style={{ width: 58, filter: `drop-shadow(0 0 ${5 + bull * 15}px rgba(45,205,95,${0.2 + bull * 0.5}))`, opacity: 0.6 + bull * 0.4, transition: "all .9s ease" }}><img src={BULL_IMG} alt="" draggable={false} style={{ width: "100%", height: "auto", display: "block" }} /></div>
            </div>
          </div>
        </div>

        {/* timeframe (all free) */}
        <div style={{ display: "flex", gap: 6, margin: "16px 0 18px" }}>
          {FRAMES.map((f) => {
            const active = frame === f.k;
            return (
              <button key={f.k} onClick={() => setFrame(f.k)} className="mono"
                style={{ flex: 1, padding: "9px 0", fontSize: 12.5, borderRadius: 10, cursor: "pointer",
                  border: `1px solid ${active ? "rgba(255,255,255,.35)" : "rgba(255,255,255,.1)"}`,
                  background: active ? "rgba(255,255,255,.1)" : "rgba(10,9,12,.35)",
                  color: active ? "#fff" : "rgba(236,233,227,.55)", transition: "all .3s" }}>
                {f.label}
              </button>
            );
          })}
        </div>

        {/* indicators */}
        <div style={{ display: "flex", flexDirection: "column", gap: 7 }}>
          {parts.map((p, i) => {
            const Icon = ICONS[p.key] || Activity;
            const h = hueOf(p.sub);
            return (
              <div key={p.key} className="rise" style={{ animationDelay: `${i * 55}ms`, display: "flex", alignItems: "center", gap: 11, background: "rgba(12,11,15,.66)", backdropFilter: "blur(7px)", border: "1px solid rgba(255,255,255,.07)", borderRadius: 12, padding: "10px 13px" }}>
                <Icon size={16} style={{ color: `hsl(${h} 65% 60%)`, flexShrink: 0 }} />
                <div style={{ flex: 1, minWidth: 0 }}>
                  <div style={{ fontSize: 13, fontWeight: 500 }}>{p.label}</div>
                  <div style={{ height: 4, borderRadius: 3, background: "rgba(255,255,255,.09)", marginTop: 6, overflow: "hidden" }}>
                    <div style={{ height: "100%", width: `${p.sub}%`, background: `hsl(${h} 65% 52%)`, borderRadius: 3, transition: "width 1s ease, background 1s ease" }} />
                  </div>
                </div>
                <div className="mono" style={{ fontSize: 12, opacity: 0.75, minWidth: 54, textAlign: "right" }}>{p.raw}</div>
              </div>
            );
          })}
        </div>

        {/* notifications — coming soon */}
        <div style={{ marginTop: 20, display: "flex", alignItems: "center", gap: 11, background: "rgba(12,11,15,.5)", border: "1px solid rgba(255,255,255,.07)", borderRadius: 12, padding: "13px 14px" }}>
          <Bell size={16} style={{ opacity: 0.6, flexShrink: 0 }} />
          <div style={{ flex: 1, fontSize: 13, opacity: 0.8, lineHeight: 1.45 }}>Meldingen bij elke sentiment-omslag — <span style={{ opacity: 0.6 }}>binnenkort.</span></div>
        </div>

        {status === "error" && (
          <div style={{ marginTop: 16, textAlign: "center", fontSize: 13, color: "hsl(2 70% 66%)" }}>Kon marktdata niet laden. Tik op \u21BB om opnieuw te proberen.</div>
        )}

        <div style={{ flex: 1 }} />
        <div style={{ marginTop: 24, fontSize: 11, lineHeight: 1.5, opacity: 0.4, textAlign: "center" }}>
          {updated && <div className="mono" style={{ marginBottom: 6 }}>bijgewerkt {updated.toLocaleTimeString("nl-NL", { hour: "2-digit", minute: "2-digit" })}</div>}
          Sentiment o.b.v. technische indicatoren. Geen beleggingsadvies — doe eigen onderzoek.
        </div>
      </div>
    </div>
  );
}
